  (h : Set.EqOn (Prod.map f g) (Prod.map f' g') (s ×ˢ t)) (hs : s.Nonempty) : Set.EqOn g g' t

theorem Set.mk_preimage_prod_left_fn_eq_if.{u_1, u_2, u_3} {α : Type u_1} {β : Type u_2} {γ : Type u_3}
  {s : Set α} {t : Set β} {b : β} [DecidablePred fun x => x ∈ t] (f : γ → α) :
  (fun a => (f a, b)) ⁻¹' s ×ˢ t = if b ∈ t then f ⁻¹' s else ∅

theorem Set.eval_image_pi_of_notMem.{u_1, u_2} {ι : Type u_1} {α : ι → Type u_2} {s : Set ι}
  {t : (i : ι) → Set (α i)} {i : ι} [Decidable (s.pi t).Nonempty] (hi : i ∉ s) :
  Function.eval i '' s.pi t = if (s.pi t).Nonempty then Set.univ else ∅

theorem MonotoneOn.set_prod.{u_1, u_2, u_3} {α : Type u_1} {β : Type u_2} {γ : Type u_3} {s : Set α}
