theorem Set.update_mem_pi_iff.{u_1, u_2} {ι : Type u_1} {α : ι → Type u_2} {s : Set ι}
  {t : (i : ι) → Set (α i)} [DecidableEq ι] {a : (i : ι) → α i} {i : ι} {b : α i} :
  Function.update a i b ∈ s.pi t ↔ a ∈ (s \ {i}).pi t ∧ (i ∈ s → b ∈ t i)

theorem Set.prod_range_range_eq.{u_1, u_2, u_3, u_4} {α : Type u_1} {β : Type u_2} {γ : Type u_3}
  {δ : Type u_4} {m₁ : α → γ} {m₂ : β → δ} :
  Set.range m₁ ×ˢ Set.range m₂ = Set.range fun p => (m₁ p.1, m₂ p.2)

theorem Set.prodMap_image_prod.{u_1, u_2, u_3, u_4} {α : Type u_1} {β : Type u_2} {γ : Type u_3}
  {δ : Type u_4} (f : α → β) (g : γ → δ) (s : Set α) (t : Set γ) :
