  {g₂ : Z₂ → Y₂} (mapX : X₁ → X₂) (mapY : Y₁ → Y₂) (mapZ : Z₁ → Z₂) (commX : f₂ ∘ mapX = mapY ∘ f₁)
  (commZ : g₂ ∘ mapZ = mapY ∘ g₁) (p : Function.Pullback f₁ g₁) : Function.Pullback f₂ g₂

theorem Equiv.piCongrLeft_symm_preimage_univ_pi.{u_1, u_2, u_3} {ι : Type u_1} {ι' : Type u_2}
