  (⇑(Equiv.piCongrLeft α f).symm ⁻¹' Set.univ.pi fun i' => t (f i')) = Set.univ.pi t

theorem Set.piMap_image_univ_pi.{u_1, u_2, u_3} {ι : Type u_1} {α : ι → Type u_2} {β : ι → Type u_3}
