theorem Set.update_preimage_pi.{u_1, u_2} {ι : Type u_1} {α : ι → Type u_2} {s : Set ι}
  {t : (i : ι) → Set (α i)} {i : ι} [DecidableEq ι] {f : (i : ι) → α i} (hi : i ∈ s)
  (hf : ∀ j ∈ s, j ≠ i → f j ∈ t j) : Function.update f i ⁻¹' s.pi t = t i

theorem Set.univ_pi_subset_univ_pi_iff.{u_1, u_2} {ι : Type u_1} {α : ι → Type u_2}
  {t₁ t₂ : (i : ι) → Set (α i)} :
  Set.univ.pi t₁ ⊆ Set.univ.pi t₂ ↔ (∀ (i : ι), t₁ i ⊆ t₂ i) ∨ ∃ i, t₁ i = ∅

theorem Set.union_pi_inter.{u_1, u_2} {ι : Type u_1} {α : ι → Type u_2} {s₁ s₂ : Set ι}
  {t₁ t₂ : (i : ι) → Set (α i)} (ht₁ : ∀ i ∉ s₁, t₁ i = Set.univ)
  (ht₂ : ∀ i ∉ s₂, t₂ i = Set.univ) : ((s₁ ∪ s₂).pi fun i => t₁ i ∩ t₂ i) = s₁.pi t₁ ∩ s₂.pi t₂

theorem Set.disjoint_pi.{u_1, u_2} {ι : Type u_1} {α : ι → Type u_2} {s : Set ι}
  {t₁ t₂ : (i : ι) → Set (α i)} [∀ (i : ι), Nonempty (α i)] :
